type entry struct {
	key   string
	value int
}

type LRU struct {
	capacity  int
	items     map[string]*list.Element
	evictList *list.List
}

// NewLRU creates a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity:  capacity,
		items:     make(map[string]*list.Element),
		evictList: list.New(),
	}
}

// Get returns the value associated with the key and true, or 0 and false if not found.
// Getting a key marks it as most recently used.
func (c *LRU) Get(key string) (int, bool) {
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		return ent.Value.(*entry).value, true
	}
	return 0, false
}

// Put adds a value to the cache or updates an existing one.
// If the cache is full, the least recently used entry is evicted.
func (c *LRU) Put(key string, value int) {
	if c.capacity <= 0 {
		return
	}

	// If the key already exists, update the value and move to front
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		ent.Value.(*entry).value = value
		return
	}

	// If the cache is full, evict the least recently used item
	if len(c.items) >= c.capacity {
		last := c.evictList.Back()
		if last != nil {
			c.evictList.Remove(last)
			kv := last.Value.(*entry)
			delete(c.items, kv.key)
		}
	}

	// Add the new item
	ent := &entry{key: key, value: value}
	element := c.evictList.PushFront(ent)
	c.items[key] = element
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	return len(c.items)
}

